import random,numpy as np,networkx as nx,z3,time,pickle
m=15;n=5*m;N=[set()for _ in range(n)]
for i in range(5):
 for s in range(m):
  for t in range(s+1,m):
   u=i*m+s;v=((i+1)%5)*m+t;N[u].add(v);N[v].add(u)
def forb(u,v):
 if N[u]&N[v]:return True
 n2u=set().union(*(N[x]for x in N[u]));n2v=set().union(*(N[x]for x in N[v]));return bool(n2u&n2v)
def color(k,timeout=5000):
 F=[set(N[u])for u in range(n)]
 for u in range(n):
  for x in N[u]:
   for y in N[x]:F[u]|=N[y]
 x=[z3.Int('x%d'%u)for u in range(n)];s=z3.Solver();s.set(timeout=timeout)
 for v in range(n):s.add(x[v]>=0,x[v]<k)
 for u in range(n):
  for v in F[u]:
   if u<v:s.add(x[u]!=x[v])
 s.add(x[0]==0);return s.check(),sum(map(len,F))//2
accept=0;t0=time.time()
for it in range(30000):
 a,c=random.sample(range(n),2);b=random.choice(tuple(N[a]));d=random.choice(tuple(N[c]))
 if len({a,b,c,d})<4 or c in N[a] or d in N[b]:continue
 N[a].remove(b);N[b].remove(a);N[c].remove(d);N[d].remove(c)
 good=not forb(a,c)
 if good:
  N[a].add(c);N[c].add(a);good=not forb(b,d)
  if not good:N[a].remove(c);N[c].remove(a)
 if good:N[b].add(d);N[d].add(b);accept+=1
 else:N[a].add(b);N[b].add(a);N[c].add(d);N[d].add(c)
 if it%3000==0:print(it,accept,color(5),time.time()-t0,flush=True)
print('END',accept,color(5,10000));pickle.dump(N,open('workspace/agent2_switch.pkl','wb'))

